 5px}.picked-row .drag-handle{cursor:grab;color:var(--muted);font-size:18px;user-select:none;text-align:center}.picked-row .drag-handle:active{cursor:grabbing}.picked-row.dragging{opacity:.45;border-style:dashed}.picked-row.drop-before{box-shadow:0 -3px 0 var(--blue)}.picked-row.drop-after{box-shadow:0 3px 0 var(--blue)}.probe-results{display:grid;gap:8px;margin:0;padding:0;list-style:none}.probe-results li{padding:10px 12px;border:1px solid var(--line);border-radius:8px;overflow-wrap:anywhere}.usage-kpis{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;padding:14px 0 20px}.usage-kpis .stat{border-right:1px solid var(--line)}.usage-kpis .stat:last-child{border:0}.usage-kpis .stat strong{font-size:21px}.notice{position:fixed;right:20px;bottom:20px;z-index:50;max-width:min(460px,calc(100vw - 40px));padding:12px 16px;border-radius:10px;background:#23314b;color:#fff;box-shadow:0 8px 24px #0003;display:none}.notice.error{background:#a53845}.notice.show{display:block}.footer-note{padding:14px 20px;font-size:11px;color:var(--muted)}
