            <body>
              <main class="wrap">
              <header class="top">
                <div><div class="eyebrow">MODEL ROTATOR</div><h1>模型轮转</h1><p class="sub">为一个模型配置多个目标，让请求在故障时自动接力。</p></div>
                <div class="actions"><button class="btn" id="refresh" type="button">刷新</button><button class="btn" id="settingsOpen" type="button">平台设置</button><button class="btn primary" id="newRoute" type="button">＋ 新建模型</button></div>
              </header>
              <div id="baseNotice" class="banner" role="status" hidden></div>
              <div class="grid" aria-label="模型轮转摘要"><div class="stat"><span>虚拟模型</span><strong id="statRoutes">—</strong></div><div class="stat"><span>已启用模型</span><strong id="statEnabled">—</strong></div><div class="stat"><span>实际目标</span><strong id="statTargets">—</strong></div><div class="stat stat-alert"><span>已禁用目标</span><strong id="statDown">—</strong></div></div>
              <nav class="section-nav" role="tablist" aria-label="管理视图"><button class="tab" id="tabRoutes" role="tab" aria-selected="true" aria-controls="routesView" type="button">路由管理</button><button class="tab" id="tabUsage" role="tab" aria-selected="false" aria-controls="usageView" tabindex="-1" type="button">用量统计</button></nav>
              <section id="routesView" role="tabpanel" aria-labelledby="tabRoutes">
                <div class="section-head"><div><h2 id="routesTitle">虚拟模型<span id="routeCount" class="count">0 个</span></h2><p>查看当前目标，展开后管理候选模型与手动切换。</p></div><div class="actions"><span class="hint" id="routeState" role="status" aria-live="polite"></span><button class="btn small" id="probe" type="button">立即探测</button></div></div>
                <div class="list-tools"><input id="routeSearch" type="search" aria-label="搜索虚拟模型或实际目标" placeholder="搜索虚拟模型或实际目标…" autocomplete="off"><select id="routeFilter" aria-label="筛选模型状态"><option value="all">全部状态</option><option value="enabled">已启用</option><option value="disabled">已停用</option><option value="issues">含异常目标</option></select></div>
                <div id="routeRows" class="route-list"></div><div id="routeEmpty" class="empty" hidden>还没有虚拟模型。点击「新建模型」开始配置。</div>
              </section>
              <section id="usageView" role="tabpanel" aria-labelledby="tabUsage" hidden>
                <div class="section-head"><div><h2 id="usageTitle">真实模型 Token 用量</h2><p>按实际目标汇总成功请求与上游返回的 Token。</p></div><button class="btn small" id="usageRefresh" type="button">刷新统计</button></div>
                <div class="panel"><div class="toolbar"><div class="field"><label for="usageRange">时间范围</label><select id="usageRange"><option value="24h">最近 24 小时</option><option value="7d" selected>最近 7 天</option><option value="30d">最近 30 天</option><option value="custom">自定义日期</option></select></div><div class="field" id="fromWrap" hidden><label for="usageFrom">开始日期</label><input id="usageFrom" type="date"></div><div class="field" id="toWrap" hidden><label for="usageTo">结束日期（含当天）</label><input id="usageTo" type="date"></div></div><div id="usageStatus" class="state" role="status" aria-live="polite">正在加载 Token 统计…</div><div id="usageContent" hidden><div class="usage-kpis"><div class="stat"><span>总 Token</span><strong id="usageTotal">0</strong></div><div class="stat"><span>输入 Token</span><strong id="usagePrompt">0</strong></div><div class="stat"><span>输出 Token</span><strong id="usageCompletion">0</strong></div><div class="stat"><span>成功请求</span><strong id="usageRequests">0</strong></div></div><div class="table-wrap"><table class="usage-table"><thead><tr><th>真实模型</th><th class="num">请求</th><th class="num">输入 Token</th><th class="num">输出 Token</th><th class="num">总 Token</th></tr></thead><tbody id="usageRows"></tbody></table></div><div id="usageCaption" class="footer-note"></div></div></div>
              </section>
            </main>
              <section id="editLayer" class="modal-backdrop" hidden><div class="modal wide" role="dialog" aria-modal="true" aria-labelledby="editTitle"><header class="modal-head"><h2 id="editTitle">新建虚拟模型</h2><button class="btn small" type="button" data-close="editLayer" aria-label="关闭编辑">关闭</button></header><div class="modal-body"><section class="form-section"><h3><span class="section-number">01</span>基本信息</h3><div class="form-grid"><div class="field"><label for="virtualName">虚拟模型名称</label><input id="virtualName" type="text" autocomplete="off" placeholder="例如 gpt-4o-fast"><span class="hint">这是提供给客户端调用的模型名称。</span></div><div class="field"><label for="virtualEnabled">模型状态</label><select id="virtualEnabled"><option value="true">启用</option><option value="false">停用</option></select></div><div class="field"><label for="failureThreshold">失败禁用阈值</label><input id="failureThreshold" type="number" min="1" max="100" value="3"><span class="hint">普通失败达到此值后禁用目标；超时单独累计，禁用阈值为 max(此值×2,4)。成功请求或探测成功会清零计数。</span></div><div class="field"><label for="probeEndpoint">探测端点</label><select id="probeEndpoint"><option value="/v1/chat/completions">/v1/chat/completions</option><option value="/v1/completions">/v1/completions</option><option value="/v1/embeddings">/v1/embeddings</option><option value="/v1/responses">/v1/responses</option><option value="/v1/messages">/v1/messages</option></select><span class="hint">Embedding 等非对话模型请选择对应端点。</span></div></div></section><div class="editor-columns"><section class="editor-column"><h3><span class="section-number">02</span>轮转优先级<span id="pickedCount" class="count">0 个</span></h3><p class="hint">从右侧目录添加模型，优先尝试靠前的健康目标。</p><div id="picked" class="picked" aria-label="已选模型优先级"></div><p class="hint">拖动 ⋮⋮ 或使用上移 / 下移按钮调整顺序，也支持 Alt + ↑ / ↓。保存新顺序后，下次请求按新优先级选择。</p></section><section class="editor-column"><h3><span class="section-number">03</span>平台模型目录</h3><div class="field"><label class="hint" for="catalogSearch">搜索并添加实际模型</label><div class="actions"><input id="catalogSearch" type="search" placeholder="搜索模型或平台…" autocomplete="off" style="flex:1;min-width:0"><button id="catalogRefresh" class="btn small" type="button">刷新目录</button></div><span id="catalogStatus" class="hint" role="status" aria-live="polite">正在读取平台模型目录…</span><button id="catalogSettings" class="btn small" type="button" hidden>配置平台密钥</button></div><div id="catalog" class="catalog" aria-label="可选实际模型"></div></section></div></div><footer class="modal-foot"><button class="btn" type="button" data-close="editLayer">取消</button><button id="saveRoute" class="btn primary" type="button">保存虚拟模型</button></footer></div></section>
            <section id="settingsLayer" class="modal-backdrop" hidden><div class="modal" role="dialog" aria-modal="true" aria-labelledby="settingsTitle"><header class="modal-head"><h2 id="settingsTitle">平台设置</h2><button class="btn small" type="button" data-close="settingsLayer" aria-label="关闭设置">关闭</button></header><div class="modal-body"><section class="form-section"><h3>平台连接</h3><div class="field"><label for="baseUrl">平台回环地址</label><input id="baseUrl" type="url" placeholder="http://127.0.0.1:8080" autocomplete="url"><span class="hint">插件将实际请求转发到该平台地址。与平台同机时通常使用本机回环地址。</span></div><div class="field"><label for="apiKey">平台 API Key</label><input id="apiKey" type="password" autocomplete="new-password" placeholder="留空保持现有密钥"><span class="hint" id="apiKeyHint">回环请求走 <code>/v1</code>，宿主会校验下游密钥：这里必须填 Router2API 自己的 API 密钥（管理后台「密钥管理」），否则读取目录和转发请求都会返回 401。不会回显完整密钥；输入新值即可替换。</span></div><label class="hint" style="display:flex;align-items:center;gap:8px;margin:-3px 0 14px"><input id="clearApiKey" type="checkbox"> 清除已保存的平台 API Key</label></section><section class="form-section"><h3>请求等待</h3><div class="form-grid"><div class="field"><label for="firstWait">单个模型首字节等待（秒）</label><input id="firstWait" type="number" min="10" max="300" value="30"><span class="hint">一个模型等待响应头的上限。</span></div><div class="field"><label for="firstBudget">首字节总预算（秒）</label><input id="firstBudget" type="number" min="10" max="600" value="180"><span class="hint">所有候选模型合计等待上限。</span></div><div class="field"><label for="streamIdle">流式空闲超时（秒）</label><input id="streamIdle" type="number" min="5" max="600" value="30"><span class="hint">已开始的流连续无数据达到此值后视为中断。</span></div></div></section><section class="form-section"><h3>健康探测与切换</h3><div class="form-grid"><div class="field"><label for="probeInterval">后台探测间隔（分钟）</label><input id="probeInterval" type="number" min="1" max="60" value="5"><span class="hint">定时探测已禁用或有未清零失败、超时计数的目标。</span></div><div class="field"><label for="probeTimeout">单目标探测超时（秒）</label><input id="probeTimeout" type="number" min="5" max="180" value="45"><span class="hint">默认 45 秒。免费上游拥塞时单个目标十几秒无响应很常见，设得太短会把慢但可用的目标判成异常。</span></div><div class="field"><label for="demoteThreshold">失败降级阈值</label><input id="demoteThreshold" type="number" min="1" max="100" value="1"><span class="hint">失败和超时分别累计，任一计数达到此值后将目标排到候选队尾。默认 1；提高后允许短暂抖动。仅控制后续请求排序，当前请求仍会在失败时尝试下一目标。</span></div><div class="field full"><label for="activationPolicy">活跃位切换策略</label><select id="activationPolicy">
                  <option value="sticky">sticky：保留活跃目标，达到降级或禁用阈值后让位</option><option value="prefer-highest">prefer-highest：按健康状态与优先级选择</option></select><span class="hint">sticky 可避免高优先级模型短暂抖动后频繁抢回；prefer-highest 恢复后会优先使用高优先级目标。</span></div></div></section></div><footer class="modal-foot"><button class="btn" type="button" data-close="settingsLayer">取消</button><button id="saveSettings" class="btn primary" type="button">保存设置</button></footer></div></section>
              <section id="probeLayer" class="modal-backdrop" hidden><div class="modal" role="dialog" aria-modal="true" aria-labelledby="probeTitle"><header class="modal-head"><h2 id="probeTitle">模型探测结果</h2><button class="btn small" type="button" data-close="probeLayer">关闭</button></header><div class="modal-body"><div id="probeSummary" role="status" aria-live="polite" class="banner"></div><ul id="probeResults" class="probe-results"></ul></div><footer class="modal-foot"><button class="btn" type="button" data-close="probeLayer">关闭</button></footer></div></section>
              <div id="notice" class="notice" role="status" aria-live="polite"></div>
              <script>
                (()=>{
                  'use strict';
                  const $=id=>document.getElementById(id);
                  const state={virtuals:[],settings:{},catalog:[],picked:[],editing:null,noticeTimer:0};
                  const api=(method,route,body)=>window.Router2API.request(method,route,body===undefined?null:body);
                  const node=(tag,cls,text)=>{const element=document.createElement(tag);if(cls)element.className=cls;if(text!==undefined)element.textContent=String(text);return element};
                  const button=(text,cls,action,label)=>{const element=node('button','btn '+(cls||''),text);element.type='button';if(action)element.dataset.action=action;if(label)element.setAttribute('aria-label',label);return element};
                  function toast(message,error=false){const el=$('notice');el.textContent=String(message||'请求失败');el.classList.toggle('error',error);el.classList.add('show');clearTimeout(state.noticeTimer);state.noticeTimer=setTimeout(()=>el.classList.remove('show'),5000)}
                  function errorText(error){return error&&error.message?error.message:String(error||'未知错误')}
                  function number(value){const parsed=Number(value);return Number.isFinite(parsed)&&parsed>=0?parsed:0}
                  function formatNumber(value){return number(value).toLocaleString('zh-CN',{maximumFractionDigits:0})}
                  function dateLocal(date){const y=date.getFullYear(),m=String(date.getMonth()+1).padStart(2,'0'),d=String(date.getDate()).padStart(2,'0');return y+'-'+m+'-'+d}
                  function selectedRange(){const mode=$('usageRange').value,now=new Date();if(mode==='custom'){const from=$('usageFrom').value,to=$('usageTo').value;if(!from||!to)throw Error('请选择开始和结束日期');const start=new Date(from+'T00:00:00'),end=new Date(to+'T00:00:00');if(!Number.isFinite(start.getTime())||!Number.isFinite(end.getTime())||start>end)throw Error('日期范围无效：开始日期不能晚于结束日期');end.setDate(end.getDate()+1);return{from:start.toISOString(),to:end.toISOString()}}const ms=mode==='24h'?86400000:mode==='30d'?30*86400000:7*86400000;return{from:new Date(now.getTime()-ms).toISOString(),to:now.toISOString()}}
                  function addCell(row,content,cls){const cell=node('td',cls||'');if(content instanceof Node)cell.append(content);else cell.textContent=content===undefined?'':String(content);row.append(cell);return cell}
                  function targetChip(target,threshold){
                    const row=node('div','target-item');
                    const text=node('div','target-name',target.model);
                    const meta=[];
                    if(number(target.failures))meta.push('连续失败 '+number(target.failures)+'/'+number(threshold));
                    if(number(target.timeouts))meta.push('超时 '+number(target.timeouts));
                    if(number(target.firstByteMs))meta.push('首字节 '+(Math.round(number(target.firstByteMs)/100)/10)+'s');
                    if(number(target.waitSeconds))meta.push('等待上限 '+number(target.waitSeconds)+'s');
                    if(meta.length)text.append(node('span','target-meta',meta.join(' · ')));
                    row.append(text,node('span','tag '+(target.disabled?'off':target.isActive?'on':''),target.disabled?'已禁用':target.isActive?'当前使用':'待命'));
                    return row;
                  }
                  function render(){
                    const rows=$('routeRows'),expanded=new Set([...rows.querySelectorAll('.route-details[open]')].map(el=>el.dataset.name));
                    rows.replaceChildren();
                    const query=$('routeSearch').value.trim().toLowerCase(),filter=$('routeFilter').value;
                    let enabled=0,targets=0,down=0,shown=0;
                    for(const route of state.virtuals){
                      const list=Array.isArray(route.targets)?route.targets:[],bad=list.filter(item=>item.disabled).length;
                      if(route.enabled)enabled++;targets+=list.length;down+=bad;
                      const issues=bad>0||list.some(item=>number(item.failures)||number(item.timeouts));
                      if(query&&![route.virtualModel,route.callModel,...list.map(item=>item.model)].join(' ').toLowerCase().includes(query))continue;
                      if(filter==='enabled'&&!route.enabled||filter==='disabled'&&route.enabled||filter==='issues'&&!issues)continue;
                      shown++;
                      const card=node('article','route-card'),head=node('div','route-head'),identity=node('div');
                      const title=node('div','route-title'),routeName=node('span','name',route.virtualModel),stateDot=node('span','route-status-dot '+(route.enabled?'on':'off'));
                      routeName.title=route.virtualModel;stateDot.title=route.enabled?'路由已启用':'路由已停用';stateDot.setAttribute('role','img');stateDot.setAttribute('aria-label',route.enabled?'路由已启用':'路由已停用');
                      title.append(stateDot,routeName,node('span','tag '+(route.enabled?'on':''),route.enabled?'已启用':'已停用'));
                      identity.append(title,node('div','subline mono','调用 ID：'+(route.callModel||route.virtualModel)));identity.querySelector('.subline').title='调用 ID：'+(route.callModel||route.virtualModel);
                      if(Array.isArray(route.bareTargets)&&route.bareTargets.length)identity.append(node('span','chip warn',route.bareTargets.length+' 个目标缺 platform/ 前缀'));
                      const actions=node('div','row-actions'),edit=button('编辑','small','edit');edit.dataset.name=route.virtualModel;
                      const menu=node('details','route-menu'),menuToggle=node('summary','btn small','更多');menuToggle.setAttribute('aria-label','更多操作：'+route.virtualModel);
                      const menuItems=node('div','menu-items'),toggle=button(route.enabled?'停用模型':'启用模型','small','toggle'),remove=button('删除','small danger','delete');
                      toggle.dataset.name=remove.dataset.name=route.virtualModel;menuItems.append(toggle,remove);menu.append(menuToggle,menuItems);actions.append(edit,menu);head.append(identity,actions);
                      const current=node('div','current-target'),currentText=node('div'),active=list.find(item=>item.isActive||item.model===route.activeModel);
                      const currentModel=active?active.model:bad===list.length&&list.length?'暂无可用目标':'等待首次请求后自动选择';
                      currentText.append(node('div','current-label'+(active?.disabled?' health-down':''),active?.disabled?'当前目标已禁用':'当前活跃目标'),node('div','current-model',currentModel));
                      current.append(currentText,node('div','current-time',active?.disabled?'当前目标已禁用':active&&number(active.firstByteMs)?'首字节 '+(Math.round(number(active.firstByteMs)/100)/10)+' s':'按健康状态与优先级调度'));
                      const routeHealth=node('div','route-health'),healthBar=node('div','health-bar');healthBar.setAttribute('role','img');healthBar.setAttribute('aria-label','实际模型目标健康状态');
                      let healthy=0;
                      for(const target of list){
                        const segment=node('span','health-segment '+(target.disabled?'down':number(target.failures)||number(target.timeouts)?'issue':target.isActive||target.model===route.activeModel?'active':'ready'));
                        const status=target.disabled?'已禁用':number(target.failures)||number(target.timeouts)?'有失败记录':target.isActive||target.model===route.activeModel?'当前活跃':'可用';
                        segment.title=target.model+'：'+status;segment.setAttribute('aria-hidden','true');healthBar.append(segment);
                        if(!target.disabled)healthy++;
                      }
                      if(!list.length){const segment=node('span','health-segment');segment.title='尚未配置目标';healthBar.append(segment)}
                      const healthText=node('div','health-summary');healthText.append(node('span','',list.length+' 个目标'));healthText.append(node('span',bad?'health-down':'',bad?healthy+' 可用 · '+bad+' 禁用':healthy+' 个可用'));
                      routeHealth.append(healthBar,healthText);
                      const details=node('details','route-details');details.dataset.name=route.virtualModel;details.open=expanded.has(route.virtualModel);
                      const summary=node('summary'),detailHealth=node('span','health-summary');detailHealth.append(node('span','',list.length-bad+' 个可用'));if(bad)detailHealth.append(node('span','health-down',bad+' 个禁用'));
                      summary.append(node('span','details-label','展开目标详情'),detailHealth);
                      const body=node('div','details-body'),targetList=node('div','target-list');
                      list.forEach((target,index)=>{const item=targetChip({...target,isActive:!target.disabled&&(target.isActive||target.model===route.activeModel)},route.failureThreshold);item.prepend(node('span','target-order',String(index+1).padStart(2,'0')));targetList.append(item)});
                      if(!list.length)targetList.append(node('div','state','尚未配置实际目标，请编辑模型添加。'));
                      const controls=node('div','switch-controls'),label=node('label','','手动切换'),select=node('select','active-select');select.id='active-target-'+shown;label.htmlFor=select.id;select.setAttribute('aria-label','手动切换 '+route.virtualModel+' 的活跃实际模型');
                      const auto=node('option','','自动按优先级选择');auto.value='';select.append(auto);
                      for(const item of list){const option=node('option','',item.model+(item.disabled?'（已禁用，应用后恢复并清除计数）':''));option.value=item.model;option.selected=item.isActive||item.model===route.activeModel;select.append(option)}
                      const activate=button('应用切换','small soft','activate');activate.dataset.name=route.virtualModel;controls.append(label,select,activate);
                      body.append(targetList,controls,node('p','route-note','连续失败 '+(route.failureThreshold||3)+' 次后禁用目标；超时单独累计。切换从下次请求生效。探测端点：'+(route.probeEndpoint||'/v1/chat/completions')));
                      details.append(summary,body);card.append(head,current,routeHealth,details);rows.append(card);
                    }
                    $('routeCount').textContent=(shown===state.virtuals.length?'共 '+shown:'显示 '+shown+' / '+state.virtuals.length)+' 个';
                    $('statRoutes').textContent=state.virtuals.length;$('statEnabled').textContent=enabled;$('statTargets').textContent=targets;$('statDown').textContent=down;$('statDown').parentElement.classList.toggle('is-alert',down>0);
                    $('routeEmpty').hidden=shown>0;$('routeEmpty').textContent=state.virtuals.length?'没有匹配的模型，请调整搜索或筛选条件。':'还没有虚拟模型。点击「新建模型」开始配置。';
                    $('baseNotice').hidden=Boolean(state.settings.baseUrl);$('baseNotice').textContent=state.settings.baseUrl?'':'尚未配置平台回环地址。请打开「平台设置」填写地址后，再添加实际模型。';
                    $('routeState').textContent='已更新';
                  }
                  async function load(){ $('routeState').textContent='正在读取…';try{const [virtualPayload,settings]=await Promise.all([api('GET','virtual'),api('GET','settings')]);state.virtuals=Array.isArray(virtualPayload?.virtuals)?virtualPayload.virtuals:[];state.settings=settings||{};render()}catch(error){$('routeState').textContent='读取失败：'+errorText(error);toast('页面数据加载失败：'+errorText(error),true)}}
                  function openEdit(name){const route=state.virtuals.find(item=>item.virtualModel===name)||null;state.editing=route;state.picked=route&&Array.isArray(route.targets)?route.targets.map(item=>typeof item==='string'?item:item.model).filter(Boolean):[];$('editTitle').textContent=route?'编辑虚拟模型':'新建虚拟模型';$('virtualName').value=route?.virtualModel||'';$('virtualName').readOnly=Boolean(route);$('failureThreshold').value=route?.failureThreshold||3;$('virtualEnabled').value=route?.enabled===false?'false':'true';$('probeEndpoint').value=route?.probeEndpoint||'/v1/chat/completions';$('catalogSearch').value='';$('catalog').replaceChildren();$('catalogSettings').hidden=true;$('catalogStatus').textContent='正在读取平台模型目录…';$('editLayer').hidden=false;renderPicked();loadCatalog().catch(error=>{$('catalogStatus').textContent='模型目录读取失败：'+errorText(error);toast(errorText(error),true)})}
                  async function loadCatalog(){const payload=await api('GET','platform/models');state.catalog=(Array.isArray(payload?.models)?payload.models:[]).map(item=>typeof item==='string'?{id:item,name:item,platform:''}:{id:String(item?.id||''),name:String(item?.name||item?.id||''),platform:String(item?.platform||'')}).filter(item=>item.id);$('catalogStatus').textContent=state.catalog.length?'共 '+state.catalog.length+' 个平台模型':String(payload?.detail||'没有读到模型目录：请检查回环地址与 API Key');$('catalogSettings').hidden=state.catalog.length>0;renderCatalog()}
                  function renderCatalog(){const box=$('catalog'),query=$('catalogSearch').value.trim().toLowerCase();box.replaceChildren();const list=state.catalog.filter(item=>!query||(item.id+' '+item.name+' '+item.platform).toLowerCase().includes(query));if(!list.length){box.append(node('div','empty',state.catalog.length?'没有匹配模型':'请先读取平台模型目录'));return}for(const model of list){const row=node('div','catalog-row');const text=node('span','',model.name+(model.platform?' · '+model.platform:''));const add=button(state.picked.includes(model.id)?'已添加':'加入','small '+(state.picked.includes(model.id)?'soft':''),'pick');add.dataset.model=model.id;add.disabled=state.picked.includes(model.id);row.append(text,add);box.append(row)}}
                  function renderPicked(){const box=$('picked');$('pickedCount').textContent=state.picked.length+' 个';box.replaceChildren();if(!state.picked.length){box.append(node('div','empty','从模型目录加入实际模型，添加后可调整顺序。'));return}state.picked.forEach((model,index)=>{const row=node('div','picked-row');row.dataset.index=index;row.tabIndex=0;row.setAttribute('aria-label','优先级 '+(index+1)+'：'+model);const handle=node('span','drag-handle','⋮⋮');handle.draggable=true;handle.title='拖动调整顺序';handle.setAttribute('aria-hidden','true');row.append(handle,node('span','tag',String(index+1)),node('span','model',model));const up=button('上移','small','move-up','将 '+model+' 上移');up.dataset.index=index;up.disabled=index===0;const down=button('下移','small','move-down','将 '+model+' 下移');down.dataset.index=index;down.disabled=index===state.picked.length-1;const remove=button('移除','small danger','remove-model','移除 '+model);remove.dataset.index=index;row.append(up,down,remove);box.append(row)})}
                  async function saveRoute(){const name=$('virtualName').value.trim();if(!name){toast('请填写虚拟模型名称',true);$('virtualName').focus();return}if(!state.picked.length){toast('请至少选择一个实际模型',true);return}const buttonEl=$('saveRoute');buttonEl.disabled=true;try{await api('POST','virtual/save',{virtualModel:name,targets:state.picked,failureThreshold:Number($('failureThreshold').value)||3,enabled:$('virtualEnabled').value==='true',probeEndpoint:$('probeEndpoint').value});$('editLayer').hidden=true;toast('虚拟模型已保存');await load()}catch(error){toast('保存失败：'+errorText(error),true)}finally{buttonEl.disabled=false}}
                  function openSettings(){const settings=state.settings||{};$('baseUrl').value=settings.baseUrl||'http://127.0.0.1:8080';$('apiKey').value='';$('apiKey').placeholder=settings.hasApiKey?'已保存 '+(settings.apiKeyMasked||'密钥')+'；留空不修改':'未配置密钥，可留空';$('apiKeyHint').textContent=settings.hasApiKey?'当前回环密钥：'+(settings.apiKeyMasked||'已保存')+'（即 Router2API 自己的 API 密钥）；输入新密钥替换或勾选清除。':'未配置平台 API Key：读取目录与转发请求都会被宿主判为 401。';$('clearApiKey').checked=false;$('firstWait').value=settings.firstWaitSeconds||30;$('firstBudget').value=settings.firstByteBudgetSeconds||180;$('streamIdle').value=settings.streamIdleSeconds||30;$('probeInterval').value=settings.probeIntervalMinutes||5;$('probeTimeout').value=settings.probeTimeoutSeconds||45;$('demoteThreshold').value=settings.demoteThreshold||1;$('activationPolicy').value=settings.activationPolicy==='prefer-highest'?'prefer-highest':'sticky';$('settingsLayer').hidden=false}
                  async function saveSettings(){const body={baseUrl:$('baseUrl').value.trim(),firstWaitSeconds:Number($('firstWait').value),firstByteBudgetSeconds:Number($('firstBudget').value),streamIdleSeconds:Number($('streamIdle').value),probeIntervalMinutes:Number($('probeInterval').value),probeTimeoutSeconds:Number($('probeTimeout').value),demoteThreshold:Number($('demoteThreshold').value),activationPolicy:$('activationPolicy').value};const key=$('apiKey').value.trim();if(key)body.apiKey=key;if($('clearApiKey').checked)body.clearApiKey=true;const save=$('saveSettings');save.disabled=true;try{await api('POST','settings/save',body);$('settingsLayer').hidden=true;toast('平台设置已保存');await load()}catch(error){toast('设置保存失败：'+errorText(error),true)}finally{save.disabled=false}}
                  function showUsage(payload){const totals=payload?.totalsOverall||{};$('usageTotal').textContent=formatNumber(totals.totalTokens);$('usagePrompt').textContent=formatNumber(totals.promptTokens);$('usageCompletion').textContent=formatNumber(totals.completionTokens);$('usageRequests').textContent=formatNumber(totals.requests);const rows=$('usageRows');rows.replaceChildren();const models=Array.isArray(payload?.totals)?payload.totals:[];for(const item of models){const row=document.createElement('tr');addCell(row,item.model||'未知模型','name');addCell(row,formatNumber(item.requests),'num');addCell(row,formatNumber(item.promptTokens),'num');addCell(row,formatNumber(item.completionTokens),'num');addCell(row,formatNumber(item.totalTokens),'num');rows.append(row)}$('usageStatus').hidden=models.length>0;$('usageContent').hidden=models.length===0;if(!models.length){$('usageStatus').textContent='此时间范围没有成功请求记录。';return}const from=payload.from?new Date(payload.from).toLocaleString('zh-CN'):'';const to=payload.to?new Date(payload.to).toLocaleString('zh-CN'):'';$('usageCaption').textContent='时间范围：'+from+' 至 '+to+'。请求数按成功请求计；Token 取自上游返回的 usage（流式响应在流末尾补记），缺少 usage 时不估算，只计请求数。'+(payload.truncated?' 统计可能因容量上限不完整。':' 保留最近 '+(payload.retentionDays||31)+' 天。')}
