                  document.addEventListener('click',async event=>{const close=event.target.closest('[data-close]');if(close){$(close.dataset.close).hidden=true;return}const actionButton=event.target.closest('[data-action]');if(!actionButton)return;const action=actionButton.dataset.action;try{if(action==='pick'){if(!state.picked.includes(actionButton.dataset.model))state.picked.push(actionButton.dataset.model);renderPicked();renderCatalog()}else if(action==='move-up'||action==='move-down'){const index=Number(actionButton.dataset.index),to=action==='move-up'?index-1:index+1;if(to>=0&&to<state.picked.length){[state.picked[index],state.picked[to]]=[state.picked[to],state.picked[index]];renderPicked();renderCatalog()}}else if(action==='remove-model'){state.picked.splice(Number(actionButton.dataset.index),1);renderPicked();renderCatalog()}else{const name=actionButton.dataset.name;const route=state.virtuals.find(item=>item.virtualModel===name);if(action==='edit')openEdit(name);else if(action==='toggle'){await api('POST','virtual/toggle',{virtualModel:name,enabled:!route?.enabled});toast('虚拟模型状态已更新');await load()}else if(action==='delete'){if(actionButton.dataset.confirm!=='1'){actionButton.dataset.confirm='1';actionButton.textContent='再次点击确认';setTimeout(()=>{if(actionButton.isConnected){delete actionButton.dataset.confirm;actionButton.textContent='删除'}},4000);return}await api('POST','virtual/delete',{virtualModel:name});toast('已删除 '+name);await load()}else if(action==='activate'){const model=actionButton.closest('.switch-controls').querySelector('select').value;await api('POST','virtual/activate',{virtualModel:name,model});toast(model?'已手动切换活跃目标：'+model+'（从下次请求开始生效，进行中的连接不受影响）':'已恢复自动按优先级选择');await load()}}}catch(error){toast(errorText(error),true)}});
