                  // 拖动期间只显示插入位置，不重建源节点；成功放下后才修改待保存顺序。
                  const pickedBox=$('picked');let dragRow=null;
                  function clearDropMarks(){pickedBox.querySelectorAll('.drop-before,.drop-after').forEach(row=>row.classList.remove('drop-before','drop-after'))}
