                  function reorderPicked(from,to){if(!Number.isInteger(from)||!Number.isInteger(to)||from===to||from<0||to<0||from>=state.picked.length||to>=state.picked.length)return;const moved=state.picked.splice(from,1)[0];state.picked.splice(to,0,moved);renderPicked();const row=pickedBox.querySelector('[data-index="'+to+'"]');if(row)row.focus({preventScroll:true})}
                  function dropPosition(event){const row=event.target.closest('.picked-row');if(row&&pickedBox.contains(row)){const rect=row.getBoundingClientRect(),after=event.clientY>=rect.top+rect.height/2;return{row,after,index:Number(row.dataset.index)+(after?1:0)}}const rows=[...pickedBox.querySelectorAll('.picked-row')];const next=rows.find(row=>{const rect=row.getBoundingClientRect();return event.clientY<rect.top+rect.height/2});const target=next||rows[rows.length-1];return target?{row:target,after:!next,index:next?Number(next.dataset.index):rows.length}:null}
                  pickedBox.addEventListener('dragstart',event=>{const handle=event.target.closest('.drag-handle'),row=handle?.closest('.picked-row');if(!row||!pickedBox.contains(row)){event.preventDefault();return}resetPickedDrag();dragRow=row;row.classList.add('dragging');if(event.dataTransfer){event.dataTransfer.effectAllowed='move';event.dataTransfer.setData('text/plain',state.picked[Number(row.dataset.index)])}});
                  pickedBox.addEventListener('dragover',event=>{if(!dragRow)return;event.preventDefault();if(event.dataTransfer)event.dataTransfer.dropEffect='move';clearDropMarks();const target=dropPosition(event);if(target&&target.row!==dragRow)target.row.classList.add(target.after?'drop-after':'drop-before')});
