                  $('newRoute').addEventListener('click',()=>openEdit(null));$('saveRoute').addEventListener('click',saveRoute);$('catalogSearch').addEventListener('input',renderCatalog);$('catalogRefresh').addEventListener('click',()=>loadCatalog().catch(error=>{$('catalogSettings').hidden=false;toast('目录读取失败：'+errorText(error),true)}));$('catalogSettings').addEventListener('click',openSettings);$('settingsOpen').addEventListener('click',openSettings);$('saveSettings').addEventListener('click',saveSettings);$('probe').addEventListener('click',runProbe);$('usageRefresh').addEventListener('click',loadUsage);$('usageRange').addEventListener('change',()=>{const custom=$('usageRange').value==='custom';$('fromWrap').hidden=!custom;$('toWrap').hidden=!custom;if(custom){const today=new Date();$('usageTo').value=$('usageTo').value||dateLocal(today);const week=new Date(today.getTime()-7*86400000);$('usageFrom').value=$('usageFrom').value||dateLocal(week);return}loadUsage()});$('usageFrom').addEventListener('change',loadUsage);$('usageTo').addEventListener('change',loadUsage);document.addEventListener('keydown',event=>{if(event.key==='Escape')document.querySelectorAll('.modal-backdrop:not([hidden])').forEach(layer=>layer.hidden=true)});
